<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<view class="top" :style="{'backgroundImage':`url(${baseUrl}/uni/jf-shop-bg.png)`}">
			<view class="tit">我的积分(元)</view>
			<view class="money">{{user.jifen}}</view>
			<view class="bot">
				<view class="btn" @click="toNext('/pages/my/jf-money')">积分明细</view>
				<view class="center"></view>
				<view class="btn" @click="toNext(`/pages/order/jf-order-list?type=0`)">积分订单</view>
			</view>
		</view>
		<view class="goods-scroll">
			<block v-if="lists.length>0">
			<view style="height: 20rpx;"></view>
			<view class="goods-items">
				<view class="goods-item" v-for="(item,index) in lists" :key="item.goods_id" @click="toNext(`/pages/index/jf-goods-detail?goods_id=${item.goods_id}`)">
					<image :src="item.goods_img" mode="aspectFill" class="goods-img"/>
					<view class="goods-name">{{item.goods_name}}</view>
					<view class="goods-price">
						<text class="jiage">{{item.jifen}}</text>
						<text class="jifen">积分+{{item.cash}}金豆</text>
						<button size="mini" class="buy-btn">兑换</button>
					</view>
				</view>
			</view>
			<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</block>
			<view class="empty-view" v-else>
				<view class="empty-container">
					<u-empty text="暂无相关商品" :icon="emptyIcon" />
				</view>
			</view>
		</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				cate_list: [
					{'id':0,'name':'全部'}
				],
				form:{
					pageIndex:1,
					pageSize:20,
					cate_id: 0,
				}
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_user_info()
			_this.get_goods()
		},
		onReachBottom() {
			console.log('加载');
			if (_this.hasMore) {
				_this.form.pageIndex++
				_this.get_goods()
			}
		},
		methods: {
			//获取用户信息
			async get_user_info() {
				const data = await _this.$post('port/user_info')
				if (data.code == 200) {
					this.user = data.result.user
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			async get_goods_category() {
				const data = await _this.$post('port/get_jf_goods_category')
				_this.cate_list.push(...data.result.list)
				if (_this.form.cate_id == 0 && _this.cate_list.length > 0) {
					_this.form.cate_id = _this.cate_list[0]['id']
				}
				_this.get_goods()
			},
			cateClick(item){
				if (item.id == _this.form.cate_id) {
					return
				}
				_this.form.cate_id = item.id
				_this.form.pageIndex = 1
				_this.lists = []
				_this.get_goods()
			},
			async get_goods(){
				const data = await _this.$post('port/request_jf_goods',_this.form)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore=data.result.list.length>=_this.form.pageSize
				}else{
					_this.hasMore=false
				}
			}
		}
	}
</script>

